// (nie gelöscht). Unklare Mails bleiben im Posteingang.
const ARCHIVIEREN_BEI = ['ignoriert', 'ignoriert_auto_antwort', 'ignoriert_gesperrt'];

function archivieren(ergebnis) {
	return ARCHIVIEREN_BEI.includes(ergebnis);
