/**
 * A4: Klassifizierung auswerten.
 * @param {object} llm Ergebnis von "EPA SW LLM aufrufen": { ok, ergebnis } oder { ok: false, code, fehler }
 * @param {object} config Kunden-Config
 * @param {object} mail normalisierte Mail
