const GEWICHTE = Object.freeze({
	BEZUG_MESSAGE_ID: 60, // In-Reply-To/References enthält eine bekannte Message-ID
	CONVERSATION_ID: 40,
	ABSENDER_GLEICH: 25,
	DOMAIN_GLEICH: 10, // nur wenn die Adresse abweicht
