	VORGANGS_ID_GENANNT: 60, // Bauplan 5.2 sah 50 vor; mit 60 reicht "ID genannt + gleicher Absender" (85) für eindeutig
	THREAD_FREMDE_DOMAIN: -40, // Konfliktmarker
});

